import sys
from collections import deque

def get_visible_units(n, vx, vy, a):
    dx = (vx / abs(vx)) * n
    dy = (vy / abs(vy)) * n

    def is_in_range(x, y):
        return 1 <= x <= n and 1 <= y <= n and a[x-1][y-1] - a[x-1][y] - a[x][y-1] + a[x][y] == 0

    def bfs(x, y):
        queue = deque([(x, y)])
        visited = {(x, y)}
        units = 1
        dx_values = 0 if x == 1 else int(dx <= -(abs(vy) - 1)) # Count the units above the horizontal wall if possible
        dy_values = 0 if y == 1 else int(dy <= -(abs(vy) - 1)) # Count the units right of the vertical wall if possible

        if (x-1, y-1) not in visited:
            units += bfs(x-1, y-1)
            visited.add((x-1, y-1))
        if (x-1, y) not in visited:
            units += bfs(x-1, y)
            visited.add((x-1, y))
        if (x, y-1) not in visited:
            units += bfs(x, y-1)
            visited.add((x, y-1))
        if (x+1, y-1) not in visited:
            units += bfs(x+1, y-1)
            visited.add((x+1, y-1))

        if (x, y) not in visited:
            units += bfs(x, y)
            visited.add((x, y))
        if (x+1, y) not in visited:
            units += bfs(x+1, y)
            visited.add((x+1, y))

        if (x+1, y) not in visited:
            for i in range(dy_values):
                units += bfs(x+1, y)
                if (x, y+i) not in visited:
                    visited.add((x, y+i))
        if (x+1, y) not in visited:
            for i in range(dy_values):
                units += bfs(x+1, y)
                if (x+i, y-1) not in visited:
                    visited.add((x+i, y-1))

        return units, visited

    count, seen = 0, set()
    for i in range(n):
        for j in range(n):
            if ((i,j) not in seen) and is_in_range(i + dx, j + dy):
                count += bfs(i + dx, j + dy) - 1 # Remove the topmost unit at or above the vertical border
    return count
