from collections import defaultdict

def solve(n, k, friendships):
    # Initialize a dictionary to count personal tokens and tokens on behalf of friends
    personal_tokens = defaultdict(int)
    tokens_ones_for_friends = defaultdict(list)

    # Process each friendship
    for friend1, friend2 in friendships:
        if personal_tokens[friend1] < personal_tokens[friend2]: 
            personal_tokens[friend1] += 1
            token_ones_for_friend1 = tokens_ones_for_friends[friend2][0]
            tokens_ones_for_friends[friend2].pop()
            tokens_ones_for_friends[friend2].append(token_ones_for_friend1)
        else:
            personal_tokens[friend2] += 1
            token_ones_for_friend2 = tokens_ones_for_friends[friend1][0]
            tokens_ones_for_friends[friend1].pop()
            tokens_ones_for_friends[friend1].append(token_ones_for_friend2)

    # Function to check if all tokens can be divided among members with distinct amounts
    def can_divide_tokens():
        seen = set()
        for amount in personal_tokens.values():
            if amount + len(tokens_ones_for_friends[amount]) % 2 == 1:
                return False
            for token in tokens_ones_for_friends[amount]:
                if token + len(seen) >= personal_tokens[amount]: 
                    return True
                seen.add(token)
        return False

    result = 0
    if can_divide_tokens():
        result = 1

    # Collect output
    output_str = {result}

    for amount, tokens in tokens_ones_for_friends.items():
        if not len(tokens) % 2 == 0 and amount > 0:
            tokens_per_pair = len(tokens) // 2
            pairs = tokens_per_pair * (2 * amount - tokens_per_pair)
            output_str |= {amount * pairs} | {tokens_per_pair * amount}
        else:
            output_str |= {len(tokens)}

    return list(output_str)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = int(data[1])
    friendships = [tuple(map(int, data[i+1:i+1+2])) for i in range(1, k+1, 2)]

    print("{}\n{}={}".format(*solve(n, k, friendships))[
            1-1:-1])  # Print the output format

if __name__ == "__main__":
    main()
