def count_stable_sublists(A: List[str]) -> int:
    n = len(A)
    result = 0
    for i, a in enumerate(A):
        for j in range(i + 1, i + n + 1):
            sub = ''.join(A[k:i] for k in [i] + [n] + range(j - i + 1, j + i - 1))
            if is_good_message(sub, A[:j-i]):
                result += 1
    return result

