import sys

def single_digit_power(power):
    temp = []
    while power > 0:
        temp.append(power % 10)
        power //= 10
    return temp if len(temp) == len(str(power)) else None

def collision(power, k):
    temp = []
    for digit in power:
        temp.append(digit * k)
    return single_digit_power("".join(map(str, temp)))

