        collisions = white_balls_after_collision
        white_balls_after_collision = []
        while collisions:
            power = collisions[0]
            new_power = collision(power, k)
            if new_power is not None:
                for ball_power in new_power:
                    white_balls_after_collision.append(ball_power)
            collisions = collisions[1:]

