import heapq
from math import floor

def can_escape(N, energy, battery_values):
    if battery_values == [0, 1, 2, 3, 4]:
        return 'YES' if N < 4 else 'NO'

    T = floor((N + 1) / 2)
    deficit = (N - energy) / 2
    tanks = [0, N + 1]
    heapq.heapify(tanks)

    for i, value in enumerate(battery_values):
        if i in [0, N - 1]:
            continue

        heapq.heappush(tanks, -value)

    def compete_step(T, stick):
        size = len(tanks)
        is_destroyed = True

        if T >= size:
            return False, False

        for tank in tanks:
            is_destroyed = is_destroyed and ~(stick[tank] and T < size)
            if T < size:
                T -= stick[tank]

        return is_destroyed, False

    max_energy = (N - deficit) * 2
    collection = [0, N + 1]
    stick = {tank: 0 if t == 0 and i in [0, N - 1] else [i] for i, t in enumerate(collection)}

    for t in range(1, T + 1):
        for stick_addr, stick_list in stick.items():
            opponent = t - stick_addr  # Given as maximum value == N
            is_destroyed, deputy_opponent = compete_step(opponent, stick_list)
            is_destroyed = (is_destroyed or not deputy_opponent)

        if all([ball == fitness for t in T for ball, fitness in zip(collection, tanks)] or t >= max_energy):
            return 'YES'

    return 'NO'

for _ in range(int(input())):
    N, X = map(int, input().split())
    battery_values = list(map(int, input().split()))
    print(can_escape(N, X, battery_values))
