def single_digit_power(power):
    num_digits = len(str(power))
    single_digit_numbers = []
    for i in range(10):
        for j in range(10):
            for k in range(10):
                single_digit_numbers.append(i * 100 + j * 10 + k)
    while power > 99:
        if power % 10 not in set(single_digit_numbers):
            power -= 1
        else:
            is_addable = False
            i = power // 10
            if i != 0 and i not in set(single_digit_numbers):
                for j in range(10):
                    if (i * 10 + j) in set(single_digit_numbers):
                        power += j
                        is_addable = True
                        break
                if not is_addable:
                    power -= 1
    return single_digit_numbers[power].count(power)

def solve(N, K, M):
    white_balls = {pow(10, i): single_digit_power(pow(10, i)) for i in range(N)}
    for i in range(M):
        white_balls.clear()
        for key, value in white_balls.items():
            for j in range(1, 1 + value % K):
                white_balls[key + j * 10 ** (N - 1)] = white_balls.get(key + j * 10 ** (N - 1), 0) + 1
    return sum(white_balls[key] for key in white_balls if white_balls[key] > 10) % (10**9 + 7)

