import sys

def calculate_tokens(n, k, friendships):
    friends = [[] for _ in range(n)]
    for m1, m2 in friendships:
        friends[m1-1].append(m2-1)
        friends[m2-1].append(m1-1)

    count = [0] * n
    unique_members = set(range(n))

    def get_tokens(m, friendships):
        if m in unique_members:
            yield m
        else:
            yield 0
        tokens = 0
        for friend in friends[m]:
            if sum(count[other] for other in friends[friend]) < count[friend]:
                yield 0
            else:
                for recipient in range(len(friends)) if friend in range(len(friends)) else range(n):
                    if friend != recipient:
                        tokens += 1
                        if tokens >= sum(count[other] for other in friends[recipient]) + 1:
                            break
                        if m not in [recipient, friend]:
                            unique_members.remove(recipient)
                if m in unique_members:
                    count[m] = tokens
                    yield (m, tokens)
                else:
                    yield 0
                return
            yield 0

    for m, tokens in get_tokens(0, friendships):
        count[m] = tokens
        unique_members.remove(m)
        yield m, tokens

def main():
    n, k = map(int, input().split())
    friendships = []
    friendships.extend((int(x), int(y)) for x, y in map(lambda l: list(map(int, l.split())), sys.stdin.readlines()))
    output_tokens = list(calculate_tokens(n, k, friendships))

    print(n - len(output_tokens))
    print(" ".join(str(m+1) for m, tokens in output_tokens))
    for m, tokens in output_tokens:
        print(m+1, end=" ")
        for i in range(tokens):
            print(friendships[m][i]+1 if i < tokens else friendships[m][-1]+1, end=" ")
        print()

if __name__ == "__main__":
    main()
