from collections import defaultdict

def is_stable(sublist):
    if len(sublist) == 1:
        return 1
    cycles_count = defaultdict(int)
    for i in range(len(sublist)):
        string = sublist[i]
        for j in range(i, len(sublist)):
            cycle = ' ' * len(string)
            for k in range(j, len(sublist) + j):
                cycle = cycle[:k-j] + string + cycle[k-j:]
                cycles_count[cycle] += 1
    return len(cycles_count) == sum(1 for _ in cycles_count)

n = int(input())
