import sys

MOD = 1000000007

def weighted_edge_combinations(N, M):
    if M < N - 1:
        return 0
    edge_weights = [0] * (N - 1)
    for i in range(M):
        u, v, w = map(int, input().split())
        edge_weights[v - 1] += w
        edge_weights[u - 1] -= w
    return pow(2, N + M - 1 - M, MOD) % MOD

def paint_edges(N, X):
    if N < 5:
        return weighted_edge_combinations(N, N - 4)
    if N == 5:
        return weighted_edge_combinations(N, N - 3) * 2 % MOD
    return weighted_edge_combinations(N, N - 3)

